package com.example.starter.costmap.web.dto;

import jakarta.validation.constraints.Max;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Positive;

/**
 * 创建不可变地图版本请求。
 *
 * @param versionId 可选版本ID，缺省由服务端生成
 * @param width 栅格列数
 * @param height 栅格行数
 * @param resolution 米/格
 * @param inflationRadius 障碍物膨胀半径（米）
 * @param costDecay 膨胀代价指数衰减系数（1/米）
 * @param staticGrid 静态层代价矩阵（0..254，行优先 rows[y][x]），null 表示全 0
 */
public record CreateMapRequest(
        String versionId,
        @NotNull @Positive Integer width,
        @NotNull @Positive Integer height,
        @NotNull @Positive Double resolution,
        @NotNull @Min(0) Double inflationRadius,
        @NotNull @Min(0) Double costDecay,
        int[][] staticGrid) {
}

package com.example.starter.costmap.web.dto;

/**
 * 地图版本元数据响应。
 */
public record MapResponse(
        String versionId,
        int width,
        int height,
        double resolution,
        double inflationRadius,
        double costDecay,
        long seq) {
}

package com.example.starter.costmap.web.dto;

import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

/**
 * 障碍物更新请求。存活条件：当前时刻 now &lt;= timestampMs + ttlMs。
 *
 * @param requestId 客户端幂等请求ID；同参重放不重复应用，异参返回 409
 * @param sourceId 障碍物来源ID（同格合并决胜第三键）
 * @param priority 来源优先级，越大越优先（决胜第一键），缺省 0
 * @param xMin 区域最小列（含）
 * @param yMin 区域最小行（含）
 * @param xMax 区域最大列（含）
 * @param yMax 区域最大行（含）
 * @param timestampMs 障碍物事件时间戳 epoch 毫秒，缺省取服务时钟
 * @param ttlMs 存活时长毫秒
 * @param expectedSeq 可选乐观版本约束；与当前 seq 不一致返回 409
 */
public record ObstacleUpdateRequest(
        @NotBlank String requestId,
        @NotBlank String sourceId,
        Integer priority,
        @NotNull @Min(0) Integer xMin,
        @NotNull @Min(0) Integer yMin,
        @NotNull @Min(0) Integer xMax,
        @NotNull @Min(0) Integer yMax,
        Long timestampMs,
        @NotNull @Min(0) Long ttlMs,
        Long expectedSeq) {
}

package com.example.starter.costmap.web.dto;

import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotNull;

/**
 * 矩形区域请求参数。
 */
public record RegionRequest(
        @NotNull @Min(0) Integer xMin,
        @NotNull @Min(0) Integer yMin,
        @NotNull @Min(0) Integer xMax,
        @NotNull @Min(0) Integer yMax) {
}

package com.example.starter.costmap.web.dto;

/**
 * 区域代价查询响应；costs[y][x] 为相对区域偏移的代价矩阵（0..254）。
 */
public record RegionCostResponse(
        String versionId,
        String snapshotId,
        long seq,
        int xMin,
        int yMin,
        int xMax,
        int yMax,
        int[][] costs) {
}

