                "SELECT COUNT(*) FROM obstacle_update WHERE request_id = 'idem-1'", Integer.class));
        assertEquals(1, jdbc.queryForObject(
                "SELECT COUNT(*) FROM obstacle_cell WHERE request_id = 'idem-1'", Integer.class));

