// Windows 下工作目录含非 ASCII 字符时，Gradle 测试 worker 的 @argfile/classpath
// 会触发 GradleWorkerMain ClassNotFoundException。将 build 目录重定向到第一个
// 可写的 ASCII 候选路径，仅影响构建产物位置，不改变源码与工程结构。
if (!(layout.projectDirectory.asFile.absolutePath.matches('\\A\\p{ASCII}*\\z'))) {
    List<String> candidates = [
            System.getenv('ProgramData'),
            System.getProperty('java.io.tmpdir'),
            System.getProperty('user.home'),
            'E:/tmp'
    ].findAll { it != null && it.matches('\\A\\p{ASCII}*\\z') }
    File asciiRoot = null
    for (String c : candidates) {
        File f = new File(c, 'gsb-gradle-builds')
        if (f.exists() || f.mkdirs()) {
            asciiRoot = f
            break
        }
    }
    if (asciiRoot != null) {
        layout.buildDirectory = new File(asciiRoot, rootProject.name + '-022b')
        println("[build] non-ASCII project path detected; buildDir -> ${layout.buildDirectory}")
    }
}

